            if (out1 != null && !structureOk(out1)) {
                System.out.println("BAD STRUCTURE out=<" + out1 + "> from css=<" + css + ">");
                if (++failures > 20) break;
                continue;
            }
            // idempotency
            Document twice = new Cleaner(SL).clean(once);
            Element style2 = twice.selectFirst("style");
            String out2 = style2 == null ? null : style2.data();
            if (!java.util.Objects.equals(out1, out2) || !once.body().html().equals(twice.body().html())) {
                System.out.println("NOT IDEMPOTENT css=<" + css + ">");
                System.out.println("  once=<" + once.body().html() + ">");
                System.out.println("  twice=<" + twice.body().html() + ">");
                if (++failures > 20) break;
                continue;
            }
