            if (out1 != null && out1.contains("javascript") && !out1.contains("'javascript") && !out1.contains("\"javascript")
                && !out1.contains("/*") ) {
                // 'javascript' may only appear inside a string or comment in safe output
                System.out.println("LEAK? out=<" + out1 + "> from css=<" + css + ">");
                if (++failures > 20) break;
            }
        }
        System.out.println(failures == 0 ? "ALL OK" : failures + " FAILURES");
    }

    static boolean structureOk(String css) {
        int depth = 0;
        boolean lastOpenBraceEmpty = true; // detect {}
        for (int i = 0; i < css.length(); i++) {
            char c = css.charAt(i);
            if (c == '\\') { i++; continue; }
            if (c == '"' || c == '\'') {
                int k = i + 1;
                while (k < css.length()) {
                    char d = css.charAt(k);
                    if (d == '\\') { k += 2; continue; }
                    if (d == c) break;
                    k++;
                }
                i = k;
                continue;
            }
            if (c == '/' && i + 1 < css.length() && css.charAt(i + 1) == '*') {
                int e = css.indexOf("*/", i + 2);
                if (e < 0) return false; // unterminated comment in output
                i = e + 1;
                continue;
            }
            if (c == '{') {
                depth++;
                lastOpenBraceEmpty = true;
                continue;
            }
            if (c == '}') {
                depth--;
                if (depth < 0) return false;
                if (lastOpenBraceEmpty) return false; // empty rule
                continue;
            }
            if (!StyleCleaner.isCssSpace(c) && c != ';' && c != '}') lastOpenBraceEmpty = false;
        }
        if (depth != 0) return false;
        // no leading orphan semicolons / double semicolons outside strings
        String stripped = css;
        return true;
    }
}

