                o1 = c.clean(dirty);
                o2 = c.clean(o1);
                o3 = c.clean(o2);
            } catch (Throwable t) {
                System.out.println("CLEAN THREW css=<" + css + "> base=<" + base + ">"); t.printStackTrace();
                if (++failures > 10) break; continue;
            }
            if (!before.equals(dirty.body().html())) {
                System.out.println("INPUT MUTATED css=<" + css + ">");
                if (++failures > 10) break;
            }
            if (!o1.body().html().equals(o2.body().html()) || !o2.body().html().equals(o3.body().html())) {
                System.out.println("NOT A FIXED POINT css=<" + css + "> base=<" + base + ">");
                System.out.println("  o1=<" + o1.body().html() + ">");
                System.out.println("  o2=<" + o2.body().html() + ">");
                if (++failures > 10) break;
            }
        }
        System.out.println(failures == 0 ? "SEED " + seed + ": ALL OK (" + iters + ")" : failures + " FAILURES");
    }
}

