package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;

import java.util.Random;

/**
 Adversarial fuzzer (scratch, not a committed test): throws structured-random stylesheets at the Cleaner and checks
 the spec invariants - no exceptions, idempotent output, balanced/no-empty rules, no orphan separators, dangerous
 references dropped, and the input document never mutated.
 */
public class StyleSheetFuzz {
    static final String BASE = "https://example.com/a/b";
    static final Safelist SL = Safelist.relaxed().addTags("style").addAttributes(":all", "style");

    static final String[] TOKENS = {
        "p", "div", ".a", "#b", "*", ":hover", ">", "+", " ", "  ", "\n", "\t",
        "{", "}", ";", ":", "(", ")", "[", "]", "'x'", "\"y\"", "/* c */", "/*c",
        "color", "red", "margin", "0", "url(https://example.com/x.png)",
        "url(img/x.png)", "url(javascript:alert(1))", "url(//cdn/x.png)",
        "url(data:text/plain;base64,aGVsbG8=)", "expression(alert(1))",
        "@import", "@media", "screen", "@font-face", "@charset", "url(oops",
        "'oops", "\"oops", "url(&#106;avascript:1)", "\\75 rl(javascript:1)",
        "URL(JAVASCRIPT:1)", "java%73cript:1", "//cdn", "/x.png", "#frag",
        "calc(1px + 2px)", "var(--x)", "--v", "12px", "#fff", "'Arial'",
        "url(\\6a avascript:1)", "url(%2f%2fcdn)", ";;;", "{{", "}}", "@import url(x",
    };

    static final String[] BASES = {BASE, "", "https://other.test:8080/z/"};

    static String randomCss(Random r) {
        StringBuilder sb = new StringBuilder();
        int n = 1 + r.nextInt(30);
        for (int i = 0; i < n; i++) sb.append(TOKENS[r.nextInt(TOKENS.length)]);
        return sb.toString();
    }

    public static void main(String[] args) {
        Random r = new Random(args.length > 0 ? Long.parseLong(args[0]) : 42);
        int failures = 0;
        for (int iter = 0; iter < 2_000_000; iter++) {
            String css = randomCss(r);
            String base = BASES[r.nextInt(BASES.length)];
            Document dirty;
            String dirtyHtmlBefore;
            try {
                dirty = Jsoup.parseBodyFragment("<style>" + css + "</style>", base);
                dirtyHtmlBefore = dirty.body().html();
            } catch (Throwable t) {
                System.out.println("PARSE THREW for css=<" + css + ">");
                t.printStackTrace();
                if (++failures > 20) break;
                continue;
            }
            Document once;
            try {
                once = new Cleaner(SL).clean(dirty);
            } catch (Throwable t) {
                System.out.println("CLEAN THREW for css=<" + css + ">");
                t.printStackTrace();
                if (++failures > 20) break;
                continue;
            }
            // input not mutated
            if (!dirtyHtmlBefore.equals(dirty.body().html())) {
                System.out.println("INPUT MUTATED! css=<" + css + ">");
                if (++failures > 20) break;
            }
            Element style1 = once.selectFirst("style");
            String out1 = style1 == null ? null : style1.data();
            // structural checks on output
            if (out1 != null && !structureOk(out1)) {
                System.out.println("BAD STRUCTURE out=<" + out1 + "> from css=<" + css + ">");
                if (++failures > 20) break;
                continue;
            }
            // idempotency
            Document twice = new Cleaner(SL).clean(once);
            Element style2 = twice.selectFirst("style");
            String out2 = style2 == null ? null : style2.data();
            if (!java.util.Objects.equals(out1, out2) || !once.body().html().equals(twice.body().html())) {
                System.out.println("NOT IDEMPOTENT css=<" + css + ">");
                System.out.println("  once=<" + once.body().html() + ">");
                System.out.println("  twice=<" + twice.body().html() + ">");
                if (++failures > 20) break;
                continue;
            }
            // rejected dangerous payloads: the output is a fixed point, so any active dangerous reference (which a
            // further clean would drop) is caught by the idempotency check above. A surviving "javascript" spelling
            // may only sit inside a string, a comment, or an identifier/at-keyword token it is glued to by an escape;
            // assert it never appears as an actual url()/expression( call argument.
            if (out1 != null && containsActiveDangerousCall(out1)) {
                System.out.println("ACTIVE DANGEROUS CALL out=<" + out1 + "> from css=<" + css + ">");
                if (++failures > 20) break;
            }
        }
        System.out.println(failures == 0 ? "ALL OK" : failures + " FAILURES");
    }

    // True only when a plain (non-escaped, non-string, non-comment) url()/expression() call carries a script/
    // protocol-relative/unknown-scheme argument in an active token position.
    static boolean containsActiveDangerousCall(String css) {
        int n = css.length();
        for (int i = 0; i + 4 <= n; i++) {
            char c = css.charAt(i);
            if (c == '\\') { i++; continue; }
            if (c == '"' || c == '\'') {
                int k = i + 1;
                while (k < n) { char d = css.charAt(k); if (d == '\\') k += 2; else if (d == c) break; k++; }
                i = k;
                continue;
            }
            if (c == '/' && i + 1 < n && css.charAt(i + 1) == '*') {
                int e = css.indexOf("*/", i + 2);
                if (e < 0) return false;
                i = e + 1;
                continue;
            }
            String low = css.toLowerCase();
            if ((low.startsWith("url(", i) || low.startsWith("expression(", i))
                && (i == 0 || !isIdentChar(css.charAt(i - 1)))) {
                String head = low.substring(i, Math.min(n, i + 40));
                if (head.contains("javascript") || head.contains("vbscript")
                    || head.startsWith("url(//") || head.startsWith("url(\\/")
                    || head.startsWith("url(%2f%2f") || head.startsWith("url(//"))
                    return true;
            }
        }
        return false;
    }

    static boolean isIdentChar(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_';
    }

    static boolean structureOk(String css) {
        // mask strings and comments, then check brace balance, no empty blocks, no orphan/duplicate ';'
        StringBuilder m = new StringBuilder();
        int n = css.length();
        for (int i = 0; i < n; i++) {
            char c = css.charAt(i);
            if (c == '\\') { m.append('x'); if (i + 1 < n) { m.append('x'); i++; } continue; }
            if (c == '"' || c == '\'') {
                m.append(' ');
                int k = i + 1;
                while (k < n) { char d = css.charAt(k); if (d == '\\') k += 2; else if (d == c) break; k++; }
                m.append(' ');
                i = k;
                continue;
            }
            if (c == '/' && i + 1 < n && css.charAt(i + 1) == '*') {
                int e = css.indexOf("*/", i + 2);
                if (e < 0) return false;
                while (i <= e) { m.append(' '); i++; }
                i--;
                continue;
            }
            m.append(c);
        }
        String s = m.toString();
        int depth = 0;
        char prev = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (isCssSpace(c)) continue;
            if (c == '{') {
                depth++;
                if (prev == '{') return false; // nested empty handled at its own close, but rule right after '{' checked at '}'
            } else if (c == '}') {
                depth--;
                if (depth < 0 || prev == '{') return false; // an empty block never survives
            } else if (c == ';') {
                if (prev == ';' || prev == '{' || prev == '}' || prev == 0) return false; // orphan separator
            }
            prev = c;
        }
        return depth == 0;
    }

    static boolean isCssSpace(char c) {
        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
    }
}

