package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;

import java.util.Random;

/** Multi-<style> + inline-style fuzzer: independence, order, per-document base, fixed point, input isolation. */
public class StyleMultiFuzz {
    static final String BASE = "https://example.com/a/b";
    static final Safelist SL = Safelist.relaxed().addTags("style").addAttributes(":all", "style");
    static final String[] BASES = {BASE, "", "https://other.test:8080/z/"};

    static final String[] TOKENS = {
        "p", " ", "\n", "{", "}", ";", ":", "(", ")", "'x'", "/* c */", "/*c",
        "color:red", "margin:0", "url(https://example.com/x.png)", "url(img/x.png)",
        "url(javascript:alert(1))", "url(//cdn/x.png)", "@media", "screen",
        "@import url(https://example.com/x.css)", "url(oops", "'oops", "12px",
        "\\75 rl(javascript:1)", "\\", "@font-face", "url(&#106;avascript:1)", ";;;",
    };
    static final String[] INLINE = {
        "color:red", "background:url(javascript:1);margin:0", "font:12px 'Arial'",
        "background:url(img/x.png)", "color:red;;;", "width:'oops;height:1px",
    };

    static String randomCss(Random r) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0, n = 1 + r.nextInt(20); i < n; i++) sb.append(TOKENS[r.nextInt(TOKENS.length)]);
        return sb.toString();
    }

    public static void main(String[] args) {
        long seed = args.length > 0 ? Long.parseLong(args[0]) : 1;
        int iters = args.length > 1 ? Integer.parseInt(args[1]) : 300000;
        Random r = new Random(seed);
        int failures = 0;
        for (int iter = 0; iter < iters; iter++) {
            String base = BASES[r.nextInt(BASES.length)];
            StringBuilder html = new StringBuilder();
            int styles = 1 + r.nextInt(3);
            for (int s = 0; s < styles; s++) html.append("<style>").append(randomCss(r)).append("</style>");
            html.append("<div style=\"").append(INLINE[r.nextInt(INLINE.length)]).append("\">d</div>");
            html.append("<p style=\"").append(INLINE[r.nextInt(INLINE.length)]).append("\">p</p>");
            String input = html.toString();
            Document dirty;
            String before;
            try {
                dirty = Jsoup.parseBodyFragment(input, base);
                before = dirty.body().html();
            } catch (Throwable t) {
                System.out.println("PARSE THREW " + input); t.printStackTrace();
                if (++failures > 10) break; continue;
            }
            try {
                Cleaner c = new Cleaner(SL);
                Document o1 = c.clean(dirty);
                Document o2 = c.clean(o1);
                if (!before.equals(dirty.body().html())) {
                    System.out.println("INPUT MUTATED input=<" + input + ">");
                    if (++failures > 10) break;
                }
                if (!o1.body().html().equals(o2.body().html())) {
                    System.out.println("NOT FIXED POINT base=<" + base + "> input=<" + input + ">");
                    System.out.println("  o1=<" + o1.body().html() + ">");
                    System.out.println("  o2=<" + o2.body().html() + ">");
                    if (++failures > 10) break;
                }
                // element order: surviving styles stay in document order and div/p remain after them
                int lastStyle = -1, idx = 0;
                int divAt = o1.body().html().indexOf("<div");
                for (org.jsoup.nodes.Element e : o1.select("style")) {
                    int at = o1.body().html().indexOf(e.outerHtml());
                    if (at < lastStyle) { System.out.println("STYLE ORDER CHANGED"); failures++; break; }
                    lastStyle = at;
                }
            } catch (Throwable t) {
                System.out.println("CLEAN THREW input=<" + input + ">"); t.printStackTrace();
                if (++failures > 10) break;
            }
        }
        System.out.println(failures == 0 ? "SEED " + seed + ": ALL OK (" + iters + ")" : failures + " FAILURES");
    }
}

