                int lastStyle = -1, idx = 0;
                int divAt = o1.body().html().indexOf("<div");
                for (org.jsoup.nodes.Element e : o1.select("style")) {
                    int at = o1.body().html().indexOf(e.outerHtml());
                    if (at < lastStyle) { System.out.println("STYLE ORDER CHANGED"); failures++; break; }
                    lastStyle = at;
                }
            } catch (Throwable t) {
                System.out.println("CLEAN THREW input=<" + input + ">"); t.printStackTrace();
                if (++failures > 10) break;
            }
        }
        System.out.println(failures == 0 ? "SEED " + seed + ": ALL OK (" + iters + ")" : failures + " FAILURES");
    }
}

